PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

INSERT INTO core_publication
  (publication_type, pmid, authors, title, journal, publication_date, url,
   contains_promoter_data, contains_expression_data, submission_notes, curation_complete,
   reported_TF, reported_species)
SELECT
  'ARTICLE',
  '42233522',
  'Primeaux M, Jay S, Anjum G, Grzymała-Moszczyńska H, Tovar MER',
  'I have to keep going for my kids (Tengo que seguir adelante por mis hijos): Migration, wellbeing and the collage narratives of mothers and children in transit.',
  'Women''s health (London, England)',
  '2026 Jan-Dec',
  'https://doi.org/10.1177/17455057261456862',
  0,
  0,
  'This is a test to log the taxonomies',
  1,
  'Escherichia coli',
  'Bacteroides thetaiotaomicron VPI-5482'
WHERE NOT EXISTS (
  SELECT 1 FROM core_publication WHERE pmid='42233522'
);

UPDATE core_publication
SET
  authors = CASE WHEN authors IS NULL OR authors='' THEN 'Primeaux M, Jay S, Anjum G, Grzymała-Moszczyńska H, Tovar MER' ELSE authors END,
  title = CASE WHEN title IS NULL OR title='' THEN 'I have to keep going for my kids (Tengo que seguir adelante por mis hijos): Migration, wellbeing and the collage narratives of mothers and children in transit.' ELSE title END,
  journal = CASE WHEN journal IS NULL OR journal='' THEN 'Women''s health (London, England)' ELSE journal END,
  publication_date = CASE WHEN publication_date IS NULL OR publication_date='' THEN '2026 Jan-Dec' ELSE publication_date END,
  url = CASE WHEN url IS NULL OR url='' THEN 'https://doi.org/10.1177/17455057261456862' ELSE url END,
  reported_TF = CASE WHEN reported_TF IS NULL OR reported_TF='' THEN 'Escherichia coli' ELSE reported_TF END,
  reported_species = CASE WHEN reported_species IS NULL OR reported_species='' THEN 'Bacteroides thetaiotaomicron VPI-5482' ELSE reported_species END,
  contains_promoter_data = 0,
  contains_expression_data = 0,
  curation_complete = 1,
  submission_notes = CASE
    WHEN submission_notes IS NULL OR submission_notes='' THEN 'This is a test to log the taxonomies'
    ELSE submission_notes
  END
WHERE pmid='42233522';

INSERT INTO core_tf (name, family_id, description)
SELECT 'Escherichia coli', 38, '>cccttct ccagctgaag aaatcgctaa cgcttgcaat gttagccact
ggctaatagt attgaaccgt tagatgtggg cattctcact ccagccagag
ccaccaactc tgggctggaa agtaaaaaac cgacgcaaag tcggtttttt
tacgtcctga ttcagacctc ctttcaaatg aatagccaac gcttaattca 
cacctattac cttcctctgc acatacacat tcgttaaacc atatatgttt
ttgacttatc cgcttcgaag agagacacta cctgcaacaa tcaggagcgc aat'
WHERE NOT EXISTS (
  SELECT 1 FROM core_tf WHERE lower(name)=lower('Escherichia coli')
);

UPDATE core_tf
SET
  family_id = COALESCE(family_id, 38),
  description = CASE WHEN description IS NULL THEN '>cccttct ccagctgaag aaatcgctaa cgcttgcaat gttagccact
ggctaatagt attgaaccgt tagatgtggg cattctcact ccagccagag
ccaccaactc tgggctggaa agtaaaaaac cgacgcaaag tcggtttttt
tacgtcctga ttcagacctc ctttcaaatg aatagccaac gcttaattca 
cacctattac cttcctctgc acatacacat tcgttaaacc atatatgttt
ttgacttatc cgcttcgaag agagacacta cctgcaacaa tcaggagcgc aat' ELSE description END
WHERE lower(name)=lower('Escherichia coli');

INSERT INTO core_tfinstance (refseq_accession, uniprot_accession, description, TF_id, notes)
SELECT
  'WP_002211684',
  'Q0WF12',
  'LysR family transcriptional regulator [Yersinia pseudotuberculosis YPIII].',
  (SELECT TF_id FROM core_tf WHERE lower(name)=lower('Escherichia coli') LIMIT 1),
  ''
WHERE NOT EXISTS (
  SELECT 1 FROM core_tfinstance WHERE uniprot_accession='Q0WF12'
);

UPDATE core_tfinstance
SET
  TF_id = COALESCE(TF_id, (SELECT TF_id FROM core_tf WHERE lower(name)=lower('Escherichia coli') LIMIT 1)),
  refseq_accession = COALESCE(NULLIF(refseq_accession,''), 'WP_002211684'),
  description = COALESCE(NULLIF(description,''), 'LysR family transcriptional regulator [Yersinia pseudotuberculosis YPIII].'),
  notes = COALESCE(notes, '')
WHERE uniprot_accession='Q0WF12';

INSERT INTO core_curation
  (TF_species, site_species, experimental_process, forms_complex,
   complex_notes, notes, last_modified, curator_id, publication_id, created, validated_by_id)
VALUES
  ('Bacteroides thetaiotaomicron VPI-5482', 'Bacteroides thetaiotaomicron VPI-5482', NULL,
   0, NULL, 'This is a test to log the taxonomies',
   datetime('now'), (SELECT curator_id FROM core_curator ORDER BY curator_id LIMIT 1), (SELECT publication_id FROM core_publication WHERE pmid='42233522' LIMIT 1), datetime('now'), NULL);

INSERT INTO core_curation_TF_instances (curation_id, tfinstance_id)
SELECT (SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='42233522' LIMIT 1) ORDER BY curation_id DESC LIMIT 1), (SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='Q0WF12' LIMIT 1)
WHERE NOT EXISTS (
  SELECT 1 FROM core_curation_TF_instances
  WHERE curation_id=(SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='42233522' LIMIT 1) ORDER BY curation_id DESC LIMIT 1) AND tfinstance_id=(SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='Q0WF12' LIMIT 1)
);

